    /** Icon glyph for a name such as "TIMER" or "shield_outlined" (the API sends upper-case names). */
    fun glyph(name: String?, fallback: String = "SHIELD"): String {
        val cp = codes[name?.uppercase()] ?: codes[fallback.uppercase()] ?: 0x20
        return String(Character.toChars(cp))
